inline const char* tr(const char* source){auto& c=atmor::catalog();auto i=c.find(source);return atmor::language>0&&i!=c.end()?i->second[atmor::language-1].c_str():source;}
inline std::string tr(const std::string& source){return tr(source.c_str());}
inline const wchar_t* tw(const char* source){
 static std::map<std::string,std::wstring> strings;
 std::string translated=tr(source);auto i=strings.find(translated);
 if(i==strings.end()){std::wstring_convert<std::codecvt_utf8_utf16<wchar_t>> converter;i=strings.emplace(translated,converter.from_bytes(translated)).first;}
 return i->second.c_str();
}
